<?php

declare(strict_types=1);

namespace App\DocsLab;

use InvalidArgumentException;
use JsonException;
use LastWord\Agent;

/**
 * The documents the docs-agent lab starts from, built from data every time.
 *
 * Every source .docx is WRITTEN here, by last-word, from a versioned JSON model
 * in resources/docs-lab/documents, with its pictures generated byte by byte
 * from resources/docs-lab/pictures.json. Nothing binary is committed and no
 * customer file exists anywhere: the owner's letterhead is not shared, so each
 * fixture reproduces only the STRUCTURE Moic reported.
 *
 * A picture is referred to as `png:NAME` in a document model and graded by the
 * sha256 of the bytes this class makes for NAME, so "the header holds the same
 * logo" is a byte comparison, not a resemblance.
 */
final class Fixtures
{
    /** @var array<string, string> */
    private array $pictures = [];

    public function __construct(private readonly ?string $root = null) {}

    public function root(): string
    {
        return $this->root ?? resource_path('docs-lab');
    }

    /** The bytes of a named picture. */
    public function picture(string $name): string
    {
        if (isset($this->pictures[$name])) {
            return $this->pictures[$name];
        }
        $spec = $this->json('pictures.json')['pictures'][$name] ?? null;
        if (! is_array($spec) || ! is_int($spec['width'] ?? null) || ! is_int($spec['height'] ?? null) || ! is_array($spec['rgb'] ?? null)) {
            throw new InvalidArgumentException("Unknown lab picture [{$name}].");
        }

        return $this->pictures[$name] = self::png($spec['width'], $spec['height'], $spec['rgb']);
    }

    public function pictureHash(string $name): string
    {
        return hash('sha256', $this->picture($name));
    }

    /** @return array<string, string> picture name => sha256, for every lab picture */
    public function pictureHashes(): array
    {
        $out = [];
        foreach (array_keys($this->json('pictures.json')['pictures']) as $name) {
            $out[$name] = $this->pictureHash($name);
        }

        return $out;
    }

    /** A document model with its `png:NAME` pictures resolved to data URLs. */
    public function model(string $document): array
    {
        $this->assertName($document);
        $model = $this->json('documents/'.$document.'.json')['document'] ?? null;
        if (! is_array($model)) {
            throw new InvalidArgumentException("Lab document [{$document}] has no model.");
        }

        return $this->resolve($model);
    }

    /** The .docx bytes of a lab document, written by last-word. */
    public function docx(string $document): string
    {
        return Agent::toBytes($this->model($document));
    }

    /** The raw versioned file contents a document depends on, for digests. */
    public function documentSource(string $document): string
    {
        $this->assertName($document);

        return self::lf((string) file_get_contents($this->root().'/documents/'.$document.'.json'));
    }

    public function picturesSource(): string
    {
        return self::lf((string) file_get_contents($this->root().'/pictures.json'));
    }

    /** Line endings normalised, so a digest is the same on a Windows checkout and in CI. */
    public static function lf(string $text): string
    {
        return str_replace("\r\n", "\n", $text);
    }

    /** A solid-colour PNG, byte by byte, so the fixture needs no image library. */
    public static function png(int $width, int $height, array $rgb): string
    {
        if ($width < 1 || $height < 1 || $width > 4096 || $height > 4096 || count($rgb) !== 3) {
            throw new InvalidArgumentException('A lab picture must be 1..4096 px each way with one RGB colour.');
        }
        $raw = '';
        $row = "\0".str_repeat(chr((int) $rgb[0]).chr((int) $rgb[1]).chr((int) $rgb[2]), $width);
        for ($y = 0; $y < $height; $y++) {
            $raw .= $row;
        }
        $chunk = static fn (string $type, string $data): string => pack('N', strlen($data)).$type.$data.pack('N', crc32($type.$data));

        return "\x89PNG\r\n\x1a\n"
            .$chunk('IHDR', pack('NNCCCCC', $width, $height, 8, 2, 0, 0, 0))
            .$chunk('IDAT', (string) gzcompress($raw))
            .$chunk('IEND', '');
    }

    private function resolve(mixed $value): mixed
    {
        if (is_string($value) && str_starts_with($value, 'png:')) {
            return 'data:image/png;base64,'.base64_encode($this->picture(substr($value, 4)));
        }
        if (is_array($value)) {
            return array_map(fn (mixed $item): mixed => $this->resolve($item), $value);
        }

        return $value;
    }

    private function assertName(string $name): void
    {
        if (preg_match('/^[a-z0-9][a-z0-9-]{0,63}$/D', $name) !== 1) {
            throw new InvalidArgumentException('Invalid lab document name.');
        }
    }

    /** @return array<string, mixed> */
    private function json(string $relative): array
    {
        $path = $this->root().'/'.$relative;
        if (! is_file($path)) {
            throw new InvalidArgumentException("Missing lab fixture [{$relative}].");
        }
        try {
            $decoded = json_decode((string) file_get_contents($path), true, 64, JSON_THROW_ON_ERROR);
        } catch (JsonException) {
            throw new InvalidArgumentException("Lab fixture [{$relative}] is not valid JSON.");
        }

        return is_array($decoded) ? $decoded : [];
    }
}
